const copy = (locale: Paper1Locale, en: string, vi: string) => locale === "vi" ? vi : en;
const local = (locale: Paper1Locale, value: LocalText) => value[locale];
const bool = (locale: Paper1Locale, value: boolean | null) => value === null ? "—" : value ? copy(locale, "Yes", "Có") : copy(locale, "No", "Không");
const join = (values: readonly string[]) => values.length ? values.join(" · ") : "—";

