  existence: { title: { en: "Existence check", vi: "Kiểm tra tồn tại" }, field: { en: "Course code", vi: "Mã khóa học" }, condition: { en: "Value must appear in {CS01, CS02, CS03}", vi: "Giá trị phải có trong {CS01, CS02, CS03}" }, calculationPass: { en: "CS02 is a member of the fixed table", vi: "CS02 là phần tử của bảng cố định" }, calculationFail: { en: "CS09 is absent from the fixed table", vi: "CS09 không có trong bảng cố định" }, benefit: { en: "Rejects a value absent from the declared data store", vi: "Loại giá trị không có trong kho dữ liệu đã khai báo" }, limitPass: { en: "Membership does not prove that a person or claim is genuine", vi: "Có trong bảng không chứng minh người hoặc lời khai là thật" }, limitFail: { en: "The result depends on the authorised list being current", vi: "Kết quả phụ thuộc danh sách được phép có còn cập nhật hay không" } },
  limit: { title: { en: "Limit check", vi: "Kiểm tra giới hạn" }, field: { en: "Upload size in MiB", vi: "Kích thước tải lên theo MiB" }, condition: { en: "Size ≤ 5 MiB; this rule has one upper bound", vi: "Kích thước ≤ 5 MiB; quy tắc này có một biên trên" }, calculationPass: { en: "5 equals the inclusive upper limit", vi: "5 đúng bằng giới hạn trên được tính" }, calculationFail: { en: "5.1 is greater than the upper limit 5", vi: "5,1 lớn hơn giới hạn trên 5" }, benefit: { en: "Rejects values beyond one declared bound", vi: "Loại giá trị vượt một biên đã khai báo" }, limitPass: { en: "A limit check has one bound; a range check has two", vi: "Limit check có một biên; range check có hai biên" }, limitFail: { en: "Failing the size limit says nothing about file contents", vi: "Không đạt giới hạn kích thước không cho biết nội dung tệp" } },
  "check-digit": { title: { en: "Check digit validation", vi: "Validation bằng chữ số kiểm tra" }, field: { en: "Teaching identifier", vi: "Mã định danh minh họa" }, condition: { en: "Digits 314159 use weights 7,6,5,4,3,2; check = 11 − (sum mod 11)", vi: "Các chữ số 314159 dùng trọng số 7,6,5,4,3,2; check = 11 − (tổng mod 11)" }, calculationPass: { en: "Products sum to 84; remainder 7; expected digit 4; received 4", vi: "Tổng tích bằng 84; số dư 7; chữ số cần có là 4; nhận được 4" }, calculationFail: { en: "Products sum to 84; expected digit 4; received 5", vi: "Tổng tích bằng 84; chữ số cần có là 4; nhận được 5" }, benefit: { en: "Detects many likely entry errors covered by this declared algorithm", vi: "Phát hiện nhiều lỗi nhập liệu thuộc phạm vi thuật toán đã khai báo" }, limitPass: { en: "A matching digit does not guarantee that the complete number is correct", vi: "Chữ số khớp không bảo đảm toàn bộ số là đúng" }, limitFail: { en: "This is one classroom rule, not a universal barcode algorithm", vi: "Đây là một quy tắc lớp học, không phải thuật toán barcode phổ quát" } },
