function EvidenceChain({ locale, nodes, activeIds, ticket }: { readonly locale: Paper1Locale; readonly nodes: readonly ChainNode[]; readonly activeIds: readonly string[]; readonly ticket: string }) {
  return <div className={styles.evidenceChain} role="img" aria-label={copy(locale, `Evidence chain; current evidence ${ticket}`, `Chuỗi bằng chứng; bằng chứng hiện tại ${ticket}`)}>
    {nodes.map((node, index) => <div className={styles.chainWrap} key={node.id}>
      <div className={styles.chainNode} data-active={activeIds.includes(node.id) || undefined} data-applied={activeIds.includes(node.id) && index < nodes.length - 1 || undefined}>
        <small>{node.eyebrow}</small><strong>{node.value}</strong>{activeIds.includes(node.id) ? <b aria-hidden="true">{ticket}</b> : null}
      </div>{index < nodes.length - 1 ? <i aria-hidden="true">→</i> : null}
    </div>)}
  </div>;
}

type JourneyProps = Readonly<{ locale: Paper1Locale; visualId: string; title: string; intro: string; controls: ReactNode; prediction: Prediction; scenes: readonly Scene[]; stateKey: string; onReset: () => void }>;

function Journey(props: JourneyProps) {
  return <section className={styles.lab} data-paper1-visual={props.visualId} aria-labelledby={`${props.visualId}-title`}>
    <header className={styles.header}><span>CHAPTER 6 · EVIDENCE CHAIN · {props.visualId}</span><h3 id={`${props.visualId}-title`}>{props.title}</h3><p>{props.intro}</p></header>
    <div className={styles.controls}>{props.controls}<div className={styles.controlNote}><strong>{copy(props.locale, "Inspect the declared fixture", "Quan sát tình huống đã khai báo")}</strong><span>{copy(props.locale, "Changing a selector clears the prediction and returns to evidence 01.", "Đổi lựa chọn sẽ xóa dự đoán và trở về bằng chứng 01.")}</span></div></div>
    <JourneySession key={props.stateKey} {...props} />
  </section>;
}

function JourneySession({ locale, prediction, scenes, onReset }: JourneyProps) {
  const [step, setStep] = useState(0);
  const [choice, setChoice] = useState<string>();
  const radioName = useId();
  const legendRef = useRef<HTMLLegendElement>(null);
  const safeStep = Math.min(step, scenes.length - 1);
  const current = scenes[safeStep];
  const finished = safeStep === scenes.length - 1;
  const selected = prediction.choices.find((entry) => entry.id === choice);
  const expected = prediction.choices.find((entry) => entry.id === prediction.correctChoiceId);
  const reset = () => { onReset(); setStep(0); setChoice(undefined); requestAnimationFrame(() => legendRef.current?.focus()); };
  return <>
    <fieldset className={styles.prediction}><legend ref={legendRef} tabIndex={-1}>{copy(locale, "Predict before the evidence is revealed", "Dự đoán trước khi bằng chứng được mở")}</legend><p>{prediction.prompt}</p><div>{prediction.choices.map((entry) => <label key={entry.id}><input type="radio" name={radioName} checked={choice === entry.id} onChange={() => { setStep(0); setChoice(entry.id); }} /><span>{entry.label}</span></label>)}</div><small aria-live="polite">{choice ? copy(locale, "Prediction recorded. Next now reveals one evidence change at a time.", "Đã ghi dự đoán. Tiếp theo sẽ mở từng thay đổi bằng chứng.") : copy(locale, "Choose one answer to unlock evidence 01.", "Chọn một đáp án để mở bằng chứng 01.")}</small></fieldset>
    {choice ? <div className={styles.stage} data-scene-id={current.sceneId}>
      <div className={styles.meter} style={{ "--step-count": scenes.length } as CSSProperties} role="img" aria-label={copy(locale, `Evidence ${safeStep + 1} of ${scenes.length}`, `Bằng chứng ${safeStep + 1} trên ${scenes.length}`)}>{scenes.map((_, index) => <span key={index} data-current={index === safeStep || undefined} data-complete={index < safeStep || undefined} />)}</div>
      <div className={styles.instrument}><div className={styles.canvasWrap} tabIndex={0} aria-label={copy(locale, "Interactive evidence model", "Mô hình bằng chứng tương tác")}>{current.graphic}</div><aside className={styles.receipt} aria-label={copy(locale, "Evidence ledger", "Sổ bằng chứng")}><strong>{copy(locale, "EVIDENCE LEDGER", "SỔ BẰNG CHỨNG")}</strong><dl>{current.receipt.map((entry, index) => <div key={`${entry.label}-${index}`} data-current={entry.current || undefined}><dt><span>{index + 1}</span>{entry.label}</dt><dd>{entry.value}</dd></div>)}</dl></aside></div>
      <div className={styles.explanation} aria-live="polite" aria-atomic="true"><span>{copy(locale, `EVIDENCE ${String(safeStep + 1).padStart(2, "0")}`, `BẰNG CHỨNG ${String(safeStep + 1).padStart(2, "0")}`)}</span><h4>{current.title}</h4><p>{current.explanation}</p></div>
      <div className={styles.textEquivalent}><strong>{copy(locale, "Cumulative text equivalent", "Mô tả chữ tích lũy")}</strong><p>{copy(locale, "Every revealed value, calculation and limitation remains available without relying on colour, position or motion.", "Mọi giá trị, phép tính và giới hạn đã mở vẫn đọc được mà không phụ thuộc màu sắc, vị trí hoặc chuyển động.")}</p><ol>{scenes.slice(0, safeStep + 1).map((scene, sceneIndex) => <li key={scene.sceneId} aria-current={sceneIndex === safeStep ? "step" : undefined}><h5>{copy(locale, `Evidence ${sceneIndex + 1}`, `Bằng chứng ${sceneIndex + 1}`)} · {scene.title}</h5><p>{scene.explanation}</p><dl>{scene.receipt.map((entry, index) => <div key={`${entry.label}-${index}`}><dt>{entry.label}</dt><dd>{entry.value}</dd></div>)}</dl></li>)}</ol></div>
      {finished ? <aside className={styles.comparison} data-match={choice === prediction.correctChoiceId || undefined} aria-live="polite"><strong>{choice === prediction.correctChoiceId ? copy(locale, "Prediction matched the evidence", "Dự đoán khớp với bằng chứng") : copy(locale, "Revise the prediction from the evidence", "Hãy sửa dự đoán dựa trên bằng chứng")}</strong><dl><div><dt>{copy(locale, "You chose", "Bạn chọn")}</dt><dd>{selected?.label}</dd></div><div><dt>{copy(locale, "Evidence supports", "Bằng chứng hỗ trợ")}</dt><dd>{expected?.label}</dd></div></dl></aside> : null}
      <nav className={styles.navigation} aria-label={copy(locale, "Evidence controls", "Điều khiển bằng chứng")}><Button variant="secondary" disabled={safeStep === 0} onClick={() => setStep((value) => Math.max(0, value - 1))}><ArrowLeft size={17} aria-hidden="true" />{copy(locale, "Back", "Quay lại")}</Button><Button variant="quiet" onClick={reset}><RotateCcw size={17} aria-hidden="true" />{copy(locale, "Reset", "Đặt lại")}</Button><Button disabled={finished} onClick={() => setStep((value) => Math.min(scenes.length - 1, value + 1))}>{copy(locale, "Next", "Tiếp theo")}<ArrowRight size={17} aria-hidden="true" /></Button></nav>
    </div> : <div className={styles.lockedStage} role="status" aria-live="polite"><strong>{copy(locale, "Prediction gate", "Cổng dự đoán")}</strong><p>{copy(locale, "The diagram, ledger and verdict stay hidden until you choose a prediction.", "Sơ đồ, sổ bằng chứng và kết luận được giữ kín tới khi bạn chọn dự đoán.")}</p></div>}
  </>;
}

function SecurityLab({ locale }: { readonly locale: Paper1Locale }) {
  const defaults: SecurityIncident = "stranger-read";
  const [incident, setIncident] = useState<SecurityIncident>(defaults);
  const facts = SECURITY_INCIDENTS[incident];
  const c = SECURITY_COPY[incident];
  const frames = securityIncidentFrames(incident);
  const propertySet = facts.affectedProperties.join("+");
  const choiceSets = ["security+privacy", "privacy", "integrity", "security"];
  const scenes = frames.map((frame, index): Scene => {
    const observed = index >= 2 ? local(locale, c.observed) : copy(locale, "Not observed yet", "Chưa quan sát");
    const properties = index === 3 ? facts.affectedProperties.map((item) => local(locale, PROPERTY_LABELS[item])).join(" + ") : "—";
    const target = index === 3 ? local(locale, c.target) : "—";
    return { sceneId: `P1-L37-${incident}-${frame.id}`, title: [copy(locale, "Read the protected record", "Đọc hồ sơ được bảo vệ"), copy(locale, "Inspect the trust boundary", "Quan sát ranh giới tin cậy"), copy(locale, "Record what happened", "Ghi lại điều đã xảy ra"), copy(locale, "Qualify the affected properties", "Xác định các thuộc tính bị ảnh hưởng")][index], explanation: [copy(locale, `The original mark is 80. ${local(locale, c.rights)}. Authorised purpose: ${local(locale, c.purpose)}.`, `Điểm gốc là 80. ${local(locale, c.rights)}. Mục đích được phép: ${local(locale, c.purpose)}.`), copy(locale, `${local(locale, c.actor)} attempts this action: ${local(locale, c.action)}.`, `${local(locale, c.actor)} thực hiện: ${local(locale, c.action)}.`), local(locale, c.observed), `${local(locale, c.evidence)} ${local(locale, c.limitation)}`][index], graphic: <EvidenceChain locale={locale} activeIds={frame.activeIds} ticket={frame.ticket} nodes={[{ id: "record", eyebrow: copy(locale, "PROTECTED RECORD", "HỒ SƠ ĐƯỢC BẢO VỆ"), value: copy(locale, "Student mark = 80", "Điểm học sinh = 80") }, { id: "actor", eyebrow: copy(locale, "ACTOR", "CHỦ THỂ"), value: local(locale, c.actor) }, { id: "boundary", eyebrow: copy(locale, "BOUNDARY", "RANH GIỚI"), value: local(locale, c.action) }, { id: "observed-state", eyebrow: copy(locale, "OBSERVED STATE", "TRẠNG THÁI QUAN SÁT"), value: observed }, { id: "verdict", eyebrow: copy(locale, "QUALIFIED CLAIM", "KẾT LUẬN CÓ ĐIỀU KIỆN"), value: index === 3 ? properties : copy(locale, "Not revealed", "Chưa mở") }]} />, receipt: [{ label: copy(locale, "Actor rights", "Quyền của chủ thể"), value: local(locale, c.rights), current: index === 0 }, { label: copy(locale, "Authorised purpose", "Mục đích được phép"), value: local(locale, c.purpose), current: index === 0 }, { label: copy(locale, "Attempted action", "Hành động thử thực hiện"), value: index >= 1 ? local(locale, c.action) : "—", current: index === 1 }, { label: copy(locale, "Observed access/change", "Truy cập/thay đổi quan sát được"), value: observed, current: index === 2 }, { label: copy(locale, "Affected properties", "Thuộc tính bị ảnh hưởng"), value: properties, current: index === 3 }, { label: copy(locale, "Protection target", "Đối tượng cần bảo vệ"), value: target, current: index === 3 }, { label: copy(locale, "Limitation", "Giới hạn"), value: index === 3 ? local(locale, c.limitation) : "—", current: index === 3 }] };
  });
  return <Journey locale={locale} visualId="VIS-P1-L37" title={copy(locale, "Security, privacy and integrity evidence ledger", "Sổ bằng chứng về bảo mật, quyền riêng tư và toàn vẹn")} intro={copy(locale, "Trace the actor, permitted purpose, observed access or value change, then justify every affected property.", "Theo dõi chủ thể, mục đích được phép, truy cập hoặc thay đổi giá trị, rồi giải thích từng thuộc tính bị ảnh hưởng.")} stateKey={incident} onReset={() => setIncident(defaults)} controls={<Select id="p1-l37-incident" label={copy(locale, "Incident", "Sự cố")} value={incident} onChange={(event) => setIncident(event.target.value as SecurityIncident)}>{(Object.keys(SECURITY_INCIDENTS) as SecurityIncident[]).map((id) => <option key={id} value={id}>{local(locale, SECURITY_COPY[id].title)}</option>)}</Select>} prediction={{ prompt: copy(locale, "Which property or set of properties will the evidence show as affected?", "Bằng chứng sẽ cho thấy thuộc tính nào bị ảnh hưởng?"), choices: choiceSets.map((id) => ({ id, label: id.split("+").map((item) => local(locale, PROPERTY_LABELS[item as SecurityProperty])).join(" + ") })), correctChoiceId: propertySet }} scenes={scenes} />;
}

function ThreatLab({ locale }: { readonly locale: Paper1Locale }) {
  const defaults = { path: "phishing" as ThreatPath, applied: true };
  const [path, setPath] = useState<ThreatPath>(defaults.path);
  const [applied, setApplied] = useState(defaults.applied);
  const c = THREAT_COPY[path];
  const frames = threatProtectionFrames(path, applied);
  const outcome = applied ? c.protectedOutcome : c.unprotectedOutcome;
  const assetState = applied ? c.protectedState : c.unprotectedState;
  const risk = applied ? c.protectedRisk : c.unprotectedRisk;
  const correct = applied ? "reduced" : "continues";
  const scenes = frames.map((frame, index): Scene => ({ sceneId: `P1-L38-${path}-${applied ? "applied" : "omitted"}-${frame.id}`, title: [copy(locale, "Identify source and asset", "Xác định nguồn và tài sản"), copy(locale, "Follow the threat step", "Theo dõi bước đe dọa"), copy(locale, "Inspect the control checkpoint", "Quan sát checkpoint kiểm soát"), copy(locale, "Audit outcome and remaining risk", "Đánh giá kết quả và rủi ro còn lại")][index], explanation: [copy(locale, `${local(locale, c.actor)} targets ${local(locale, c.asset)}.`, `${local(locale, c.actor)} nhắm tới ${local(locale, c.asset)}.`), local(locale, c.step), applied ? copy(locale, `${local(locale, c.control)} acts ${local(locale, c.point)}.`, `${local(locale, c.control)} hoạt động ${local(locale, c.point)}.`) : copy(locale, `The relevant control is omitted at ${local(locale, c.boundary)}.`, `Biện pháp liên quan không được áp dụng tại ${local(locale, c.boundary)}.`), `${local(locale, outcome)}. ${copy(locale, "Remaining risk:", "Rủi ro còn lại:")} ${local(locale, risk)}.`][index], graphic: <EvidenceChain locale={locale} activeIds={frame.activeIds} ticket={frame.ticket} nodes={[{ id: "source", eyebrow: copy(locale, "SOURCE", "NGUỒN"), value: local(locale, c.actor) }, { id: "threat", eyebrow: copy(locale, "THREAT STEP", "BƯỚC ĐE DỌA"), value: local(locale, c.step) }, { id: "boundary", eyebrow: copy(locale, "TRUST BOUNDARY", "RANH GIỚI TIN CẬY"), value: local(locale, c.boundary) }, { id: "control", eyebrow: copy(locale, "CONTROL STATE", "TRẠNG THÁI KIỂM SOÁT"), value: index >= 2 ? (applied ? local(locale, c.control) : copy(locale, "Relevant control not applied", "Không áp dụng biện pháp liên quan")) : copy(locale, "Not inspected", "Chưa quan sát") }, { id: "asset-state", eyebrow: copy(locale, "ASSET STATE", "TRẠNG THÁI TÀI SẢN"), value: index === 3 ? local(locale, assetState) : copy(locale, "Not revealed", "Chưa mở") }]} />, receipt: [{ label: copy(locale, "Threat mechanism", "Cơ chế đe dọa"), value: local(locale, c.step), current: index === 1 }, { label: copy(locale, "Trust boundary", "Ranh giới tin cậy"), value: local(locale, c.boundary), current: index === 1 }, { label: copy(locale, "Relevant control", "Biện pháp liên quan"), value: local(locale, c.control) }, { label: copy(locale, "Control applied", "Đã áp dụng biện pháp"), value: bool(locale, applied), current: index === 2 }, { label: copy(locale, "Outcome", "Kết quả"), value: index >= 2 ? local(locale, outcome) : "—", current: index === 2 }, { label: copy(locale, "Protected asset state", "Trạng thái tài sản"), value: index === 3 ? local(locale, assetState) : "—", current: index === 3 }, { label: copy(locale, "Remaining risk", "Rủi ro còn lại"), value: index === 3 ? local(locale, risk) : "—", current: index === 3 }] }));
  return <Journey locale={locale} visualId="VIS-P1-L38" title={copy(locale, "Threat path and control checkpoint", "Đường đe dọa và checkpoint kiểm soát")} intro={copy(locale, "Place a relevant control at the boundary, inspect what changes and retain the residual risk.", "Đặt biện pháp phù hợp tại ranh giới, quan sát điều thay đổi và giữ lại rủi ro còn lại.")} stateKey={`${path}-${applied}`} onReset={() => { setPath(defaults.path); setApplied(defaults.applied); }} controls={<><Select id="p1-l38-path" label={copy(locale, "Threat/protection path", "Đường đe dọa/bảo vệ")} value={path} onChange={(event) => setPath(event.target.value as ThreatPath)}>{(Object.keys(THREAT_PATHS) as ThreatPath[]).map((id) => <option key={id} value={id}>{local(locale, THREAT_COPY[id].title)}</option>)}</Select><Select id="p1-l38-control" label={copy(locale, "Control state", "Trạng thái kiểm soát")} value={applied ? "applied" : "omitted"} onChange={(event) => setApplied(event.target.value === "applied")}><option value="applied">{copy(locale, "Applied", "Được áp dụng")}</option><option value="omitted">{copy(locale, "Not applied", "Không áp dụng")}</option></Select><div className={styles.conditionCard}><strong>{copy(locale, "Named boundary and control", "Ranh giới và biện pháp cụ thể")}</strong><span>{local(locale, c.boundary)} · {local(locale, c.control)}</span></div></>} prediction={{ prompt: copy(locale, "Will this authored route reach the harmful outcome under the displayed control state?", "Đường đã cho có đi tới kết quả gây hại với trạng thái kiểm soát đang hiển thị không?"), choices: [{ id: "reduced", label: copy(locale, "The relevant control interrupts or exposes the route", "Biện pháp liên quan ngắt hoặc làm lộ đường đe dọa") }, { id: "continues", label: copy(locale, "The threat route continues to the authored harmful state", "Đường đe dọa tiếp tục tới trạng thái gây hại đã cho") }, { id: "eliminated", label: copy(locale, "All risk is eliminated", "Mọi rủi ro bị loại bỏ") }], correctChoiceId: correct }} scenes={scenes} />;
}

function CheckDigitWork({ locale, visible }: { readonly locale: Paper1Locale; readonly visible: boolean }) {
  if (!visible) return null;
  const digits = [3, 1, 4, 1, 5, 9]; const weights = [7, 6, 5, 4, 3, 2];
  return <div className={styles.localScroll} tabIndex={0} aria-label={copy(locale, "Check digit calculation table", "Bảng tính chữ số kiểm tra")}><table><caption>{copy(locale, "Declared teaching algorithm", "Thuật toán minh họa đã khai báo")}</caption><thead><tr><th>{copy(locale, "Digit", "Chữ số")}</th>{digits.map((value, index) => <th key={index}>{value}</th>)}</tr></thead><tbody><tr><th scope="row">{copy(locale, "Weight", "Trọng số")}</th>{weights.map((value, index) => <td key={index}>{value}</td>)}</tr><tr><th scope="row">{copy(locale, "Product", "Tích")}</th>{digits.map((value, index) => <td key={index}>{value * weights[index]}</td>)}</tr></tbody></table><p>Σ = 84 · 84 mod 11 = 7 · 11 − 7 = <strong>4</strong></p></div>;
}

function ValidationLab({ locale }: { readonly locale: Paper1Locale }) {
  const defaults = { rule: "range" as ValidationRule, fixture: "passes" as ValidationFixture };
  const [rule, setRule] = useState<ValidationRule>(defaults.rule);
  const [fixture, setFixture] = useState<ValidationFixture>(defaults.fixture);
  const facts = VALIDATION_FIXTURES[rule][fixture];
  const c = RULE_COPY[rule];
  const frames = validationFrames(rule, fixture);
  const calculation = fixture === "passes" ? c.calculationPass : c.calculationFail;
  const limitation = fixture === "passes" ? c.limitPass : c.limitFail;
  const scenes = frames.map((frame, index): Scene => ({ sceneId: `P1-L39-${rule}-${fixture}-${frame.id}`, title: [copy(locale, "Receive the exact input", "Nhận input chính xác"), copy(locale, "Declare the rule", "Khai báo quy tắc"), copy(locale, "Apply the condition", "Áp dụng điều kiện"), copy(locale, "Return a qualified verdict", "Trả về kết luận có điều kiện")][index], explanation: [copy(locale, `${local(locale, c.field)} receives “${facts.input}”. No result is inferred yet.`, `${local(locale, c.field)} nhận “${facts.input}”. Chưa suy ra kết quả.`), local(locale, c.condition), local(locale, calculation), copy(locale, `${facts.pass ? "PASS" : "FAIL"}. ${local(locale, c.benefit)}. Limitation: ${local(locale, limitation)}.`, `${facts.pass ? "ĐẠT" : "KHÔNG ĐẠT"}. ${local(locale, c.benefit)}. Giới hạn: ${local(locale, limitation)}.`)][index], graphic: <div className={styles.modelStack}><EvidenceChain locale={locale} activeIds={frame.activeIds} ticket={frame.ticket} nodes={[{ id: "input", eyebrow: copy(locale, "INPUT", "INPUT"), value: JSON.stringify(facts.input) }, { id: "rule", eyebrow: copy(locale, "DECLARED RULE", "QUY TẮC ĐÃ KHAI BÁO"), value: index >= 1 ? local(locale, c.condition) : copy(locale, "Not applied", "Chưa áp dụng") }, { id: "calculation", eyebrow: copy(locale, "TEST", "PHÉP KIỂM TRA"), value: index >= 2 ? local(locale, calculation) : copy(locale, "Not revealed", "Chưa mở") }, { id: "verdict", eyebrow: copy(locale, "QUALIFIED VERDICT", "KẾT LUẬN CÓ ĐIỀU KIỆN"), value: index === 3 ? (facts.pass ? "PASS" : "FAIL") : copy(locale, "Not revealed", "Chưa mở") }]} /><CheckDigitWork locale={locale} visible={rule === "check-digit" && index >= 2} /></div>, receipt: [{ label: copy(locale, "Classification", "Phân loại"), value: copy(locale, "Validation", "Validation") }, { label: copy(locale, "Field purpose", "Mục đích trường"), value: local(locale, c.field), current: index === 0 }, { label: copy(locale, "Input", "Input"), value: JSON.stringify(facts.input), current: index === 0 }, { label: copy(locale, "Condition", "Điều kiện"), value: index >= 1 ? local(locale, c.condition) : "—", current: index === 1 }, { label: copy(locale, "Calculation", "Phép tính/so sánh"), value: index >= 2 ? local(locale, calculation) : "—", current: index === 2 }, { label: copy(locale, "Verdict", "Kết luận"), value: index === 3 ? (facts.pass ? copy(locale, "PASS", "ĐẠT") : copy(locale, "FAIL", "KHÔNG ĐẠT")) : "—", current: index === 3 }, { label: copy(locale, "Integrity benefit", "Lợi ích toàn vẹn"), value: index === 3 ? local(locale, c.benefit) : "—", current: index === 3 }, { label: copy(locale, "Limitation", "Giới hạn"), value: index === 3 ? local(locale, limitation) : "—", current: index === 3 }] }));
  const setRuleAndResetFixture = (next: ValidationRule) => { setRule(next); setFixture("passes"); };
  return <Journey locale={locale} visualId="VIS-P1-L39" title={copy(locale, "Seven-rule validation gatebench", "Bàn validation với bảy quy tắc")} intro={copy(locale, "Apply the seven checks required by the 2026 syllabus and keep valid separate from factually correct.", "Áp dụng bảy kiểm tra của syllabus 2026 và phân biệt hợp lệ với đúng trong thực tế.")} stateKey={`${rule}-${fixture}`} onReset={() => { setRule(defaults.rule); setFixture(defaults.fixture); }} controls={<><Select id="p1-l39-rule" label={copy(locale, "Validation rule", "Quy tắc validation")} value={rule} onChange={(event) => setRuleAndResetFixture(event.target.value as ValidationRule)}>{(Object.keys(VALIDATION_FIXTURES) as ValidationRule[]).map((id) => <option key={id} value={id}>{local(locale, RULE_COPY[id].title)}</option>)}</Select><Select id="p1-l39-fixture" label={copy(locale, "Input fixture", "Tình huống input")} value={fixture} onChange={(event) => setFixture(event.target.value as ValidationFixture)}><option value="passes">A · {JSON.stringify(VALIDATION_FIXTURES[rule].passes.input)}</option><option value="fails">B · {JSON.stringify(VALIDATION_FIXTURES[rule].fails.input)}</option></Select><div className={styles.conditionCard}><strong>{copy(locale, "Condition visible before prediction", "Điều kiện hiển thị trước dự đoán")}</strong><span>{local(locale, c.condition)}</span></div></>} prediction={{ prompt: copy(locale, "Under the displayed rule, will this exact input pass or fail?", "Theo quy tắc đang hiển thị, input này sẽ đạt hay không đạt?"), choices: [{ id: "pass", label: copy(locale, "PASS", "ĐẠT") }, { id: "fail", label: copy(locale, "FAIL", "KHÔNG ĐẠT") }], correctChoiceId: facts.pass ? "pass" : "fail" }} scenes={scenes} />;
}

function BitRows({ locale, source, received, changedPositions, matrix }: { readonly locale: Paper1Locale; readonly source: readonly string[]; readonly received: readonly string[]; readonly changedPositions: readonly string[]; readonly matrix: boolean }) {
  const changed = new Set(changedPositions);
  const row = (bits: string, rowIndex: number, receivedRow: boolean) => <div className={styles.bitRow} role="row">{bits.split("").map((bit, columnIndex) => { const id = matrix ? `row-${rowIndex}-column-${columnIndex}` : `bit-${columnIndex}`; return <span role="cell" key={columnIndex} data-changed={receivedRow && changed.has(id) || undefined} aria-label={copy(locale, `${receivedRow ? "Received" : "Source"} row ${rowIndex}, bit ${columnIndex}: ${bit}${receivedRow && changed.has(id) ? ", changed" : ""}`, `${receivedRow ? "Nhận" : "Nguồn"} hàng ${rowIndex}, bit ${columnIndex}: ${bit}${receivedRow && changed.has(id) ? ", đã đổi" : ""}`)}>{bit}</span>; })}</div>;
  return <div className={styles.bitCompare} role="table" aria-label={copy(locale, "Source and received bit comparison", "So sánh bit nguồn và bit nhận")}><section><strong>{copy(locale, "SOURCE", "NGUỒN")}</strong>{source.map((bits, index) => <div key={index}>{row(bits, index, false)}</div>)}</section><section><strong>{copy(locale, "ENTERED / RECEIVED", "ĐÃ NHẬP / NHẬN")}</strong>{received.map((bits, index) => <div key={index}>{row(bits, index, true)}</div>)}</section></div>;
}

function VerificationGraphic({ locale, method, fixture, index, activeIds, ticket }: { readonly locale: Paper1Locale; readonly method: VerificationMethod; readonly fixture: VerificationFixture; readonly index: number; readonly activeIds: readonly string[]; readonly ticket: string }) {
  const facts = verificationFacts(method, fixture);
  const source = facts.source.join(method === "block-parity" ? " / " : " · ");
  const received = facts.enteredOrReceived.join(method === "block-parity" ? " / " : " · ");
  const recomputed = Array.isArray(facts.recomputedCheck) ? facts.recomputedCheck.join(" · ") : String(facts.recomputedCheck);
  return <div className={styles.modelStack}><EvidenceChain locale={locale} activeIds={activeIds} ticket={ticket} nodes={[{ id: "source", eyebrow: copy(locale, "SOURCE", "NGUỒN"), value: source }, { id: "check-data", eyebrow: copy(locale, "CHECK RULE / DATA", "QUY TẮC / DỮ LIỆU KIỂM TRA"), value: local(locale, METHOD_CONVENTION[method]) }, { id: "received", eyebrow: copy(locale, "ENTERED / RECEIVED", "ĐÃ NHẬP / NHẬN"), value: index >= 1 ? received : copy(locale, "Not received", "Chưa nhận") }, { id: "recomputed-check", eyebrow: copy(locale, "RECOMPUTED CHECK", "KIỂM TRA LẠI"), value: index >= 2 ? recomputed : copy(locale, "Not revealed", "Chưa mở") }, { id: "verdict", eyebrow: copy(locale, "QUALIFIED VERDICT", "KẾT LUẬN CÓ ĐIỀU KIỆN"), value: index === 3 ? (facts.detected ? copy(locale, "DETECTED", "PHÁT HIỆN") : copy(locale, "NOT DETECTED", "KHÔNG PHÁT HIỆN")) : copy(locale, "Not revealed", "Chưa mở") }]} />{(method === "byte-parity" || method === "block-parity") && index >= 1 ? <div className={styles.localScroll} tabIndex={0}><BitRows locale={locale} source={facts.source} received={facts.enteredOrReceived} changedPositions={facts.changedPositions} matrix={method === "block-parity"} />{method === "block-parity" && index >= 2 ? <p>{copy(locale, "Failed rows", "Hàng lỗi")}: {join(facts.failedRows.map(String))} · {copy(locale, "Failed columns", "Cột lỗi")}: {join(facts.failedColumns.map(String))}</p> : null}</div> : null}</div>;
}

function VerificationLab({ locale }: { readonly locale: Paper1Locale }) {
  const defaults = { method: "byte-parity" as VerificationMethod, fixture: "one-flip" as VerificationFixture };
  const [method, setMethod] = useState<VerificationMethod>(defaults.method);
  const [fixture, setFixture] = useState<VerificationFixture>(defaults.fixture);
  const facts = verificationFacts(method, fixture);
  const frames = verificationFrames(method, fixture);
  const recomputed = Array.isArray(facts.recomputedCheck) ? facts.recomputedCheck.join(" · ") : String(facts.recomputedCheck);
  const limitation = method === "visual" ? copy(locale, "A visual check depends on the source and human observation.", "Kiểm tra trực quan phụ thuộc vào nguồn và quan sát của con người.") : method === "double-entry" ? (fixture === "same-wrong-twice" ? copy(locale, "The same wrong value entered twice can match and remain undetected.", "Cùng một giá trị sai nhập hai lần có thể khớp và không bị phát hiện.") : copy(locale, "Matching entries reduce transcription risk but do not prove source correctness.", "Hai lần nhập khớp giúp giảm rủi ro chép sai nhưng không chứng minh nguồn đúng.")) : method === "byte-parity" ? (fixture === "two-flips" ? copy(locale, "An even number of flipped bits can preserve byte parity.", "Số bit bị đảo chẵn có thể giữ nguyên parity byte.") : copy(locale, "Byte parity detects a mismatch but does not locate or repair the bit.", "Parity byte phát hiện sai lệch nhưng không định vị hoặc sửa bit.")) : method === "block-parity" ? (fixture === "rectangle" ? copy(locale, "A four-corner pattern can preserve every row and column parity.", "Mẫu bốn góc có thể giữ nguyên parity của mọi hàng và cột.") : copy(locale, "A single-bit intersection does not generalise to arbitrary multiple errors.", "Giao điểm một bit không áp dụng cho mọi lỗi nhiều bit.")) : (fixture === "compensating" ? copy(locale, "+1 and −1 changes can preserve this modulo-256 checksum.", "Hai thay đổi +1 và −1 có thể giữ nguyên checksum modulo 256 này.") : copy(locale, "A checksum mismatch does not locate or repair an error.", "Checksum khác không định vị hoặc sửa lỗi."));
  const scenes = frames.map((frame, index): Scene => ({ sceneId: `P1-L40-${method}-${fixture}-${frame.id}`, title: [copy(locale, "Fix the source and checking rule", "Cố định nguồn và quy tắc kiểm tra"), copy(locale, "Enter or transmit the fixture", "Nhập hoặc truyền tình huống"), copy(locale, "Recompute and compare", "Tính lại và so sánh"), copy(locale, "State detection and its limit", "Nêu kết quả phát hiện và giới hạn")][index], explanation: [copy(locale, `Source: ${facts.source.join(" · ")}. Rule: ${local(locale, METHOD_CONVENTION[method])}.`, `Nguồn: ${facts.source.join(" · ")}. Quy tắc: ${local(locale, METHOD_CONVENTION[method])}.`), copy(locale, `Entered/received: ${facts.enteredOrReceived.join(" · ")}. Changed positions: ${join(facts.changedPositions)}.`, `Đã nhập/nhận: ${facts.enteredOrReceived.join(" · ")}. Vị trí đổi: ${join(facts.changedPositions)}.`), copy(locale, `Recomputed check: ${recomputed}.`, `Kiểm tra tính lại: ${recomputed}.`), copy(locale, `${facts.detected ? "DETECTED" : "NOT DETECTED"}. ${limitation}`, `${facts.detected ? "PHÁT HIỆN" : "KHÔNG PHÁT HIỆN"}. ${limitation}`)][index], graphic: <VerificationGraphic locale={locale} method={method} fixture={fixture} index={index} activeIds={frame.activeIds} ticket={frame.ticket} />, receipt: [{ label: copy(locale, "Method", "Phương pháp"), value: local(locale, METHOD_LABELS[method]), current: index === 0 }, { label: copy(locale, "Convention", "Quy ước"), value: local(locale, METHOD_CONVENTION[method]), current: index === 0 }, { label: copy(locale, "Source", "Nguồn"), value: facts.source.join(" · ") }, { label: copy(locale, "Entered/received", "Đã nhập/nhận"), value: index >= 1 ? facts.enteredOrReceived.join(" · ") : "—", current: index === 1 }, { label: copy(locale, "Changed positions", "Vị trí đổi"), value: index >= 1 ? join(facts.changedPositions) : "—", current: index === 1 }, { label: copy(locale, "Recomputed check", "Kiểm tra tính lại"), value: index >= 2 ? recomputed : "—", current: index === 2 }, { label: copy(locale, "Failed rows / columns", "Hàng / cột lỗi"), value: index >= 2 && method === "block-parity" ? `${join(facts.failedRows.map(String))} / ${join(facts.failedColumns.map(String))}` : "—", current: index === 2 && method === "block-parity" }, { label: copy(locale, "Detected", "Phát hiện"), value: index === 3 ? bool(locale, facts.detected) : "—", current: index === 3 }, { label: copy(locale, "Correctable in this fixture", "Có thể sửa trong tình huống này"), value: index === 3 ? bool(locale, facts.correctableUnderFixture) : "—", current: index === 3 }, { label: copy(locale, "Limitation", "Giới hạn"), value: index === 3 ? limitation : "—", current: index === 3 }] }));
  const setMethodAndFixture = (next: VerificationMethod) => { setMethod(next); setFixture(VERIFICATION_FIXTURES[next][0]); };
  return <Journey locale={locale} visualId="VIS-P1-L40" title={copy(locale, "Entry verification and transfer-check bench", "Bàn verification khi nhập và kiểm tra khi truyền")} intro={copy(locale, "Compare entry methods with parity and checksum, including an exact error pattern each method can miss.", "So sánh phương pháp nhập với parity và checksum, gồm một mẫu lỗi chính xác mà mỗi phương pháp có thể bỏ sót.")} stateKey={`${method}-${fixture}`} onReset={() => { setMethod(defaults.method); setFixture(defaults.fixture); }} controls={<><Select id="p1-l40-method" label={copy(locale, "Method", "Phương pháp")} value={method} onChange={(event) => setMethodAndFixture(event.target.value as VerificationMethod)}>{(Object.keys(VERIFICATION_FIXTURES) as VerificationMethod[]).map((id) => <option key={id} value={id}>{local(locale, METHOD_LABELS[id])}</option>)}</Select><Select id="p1-l40-fixture" label={copy(locale, "Method-specific fixture", "Tình huống riêng của phương pháp")} value={fixture} onChange={(event) => setFixture(event.target.value as VerificationFixture)}>{VERIFICATION_FIXTURES[method].map((id) => <option key={id} value={id}>{local(locale, FIXTURE_LABELS[id])}</option>)}</Select><div className={styles.conditionCard}><strong>{copy(locale, "Declared convention", "Quy ước đã khai báo")}</strong><span>{local(locale, METHOD_CONVENTION[method])}</span></div></>} prediction={{ prompt: copy(locale, "Will this exact method and fixture detect a mismatch?", "Phương pháp và tình huống chính xác này có phát hiện sai lệch không?"), choices: [{ id: "detected", label: copy(locale, "Detected", "Phát hiện") }, { id: "not-detected", label: copy(locale, "Not detected", "Không phát hiện") }], correctChoiceId: facts.detected ? "detected" : "not-detected" }} scenes={scenes} />;
}

export function Chapter6VisualLab({ lessonId, locale }: { readonly lessonId: string; readonly locale: Paper1Locale }) {
  if (lessonId === "P1-L37") return <SecurityLab locale={locale} />;
  if (lessonId === "P1-L38") return <ThreatLab locale={locale} />;
  if (lessonId === "P1-L39") return <ValidationLab locale={locale} />;
  if (lessonId === "P1-L40") return <VerificationLab locale={locale} />;
  return null;
}
